<script setup lang="ts">
import {ref,computed,onMounted,onBeforeUnmount,watch,nextTick} from 'vue'
import {useAuthStore} from '@/stores/auth'
import {useAuthDialogStore} from '@/stores/auth-dialog'
import {getGeneration,onRemoteIdentityChange} from '@/auth/token-session'
import {writingPersonal,setWritingFavorite,cancelWritingFavorite,saveWritingImitation,type PublishedWriting,type PersonalWriting} from '@/api/writing'
import {errorMessage} from '@/api/identity'
import {ApiError} from '@/api/client'
import WritingContentBody from './WritingContentBody.vue'
import {useRoute,onBeforeRouteLeave,onBeforeRouteUpdate} from 'vue-router'
import {useWritingIntent,type WritingIntent} from '@/stores/writing-intent'
const props=withDefaults(defineProps<{materialId:string;material?:PublishedWriting;initialFavorite?:boolean;resume?:WritingIntent}>(),{initialFavorite:undefined}),emit=defineEmits<{close:[];changed:[value:PersonalWriting]}>()
const intent=useWritingIntent(),route=useRoute()
const auth=useAuthStore(),login=useAuthDialogStore(),dialog=ref<HTMLDialogElement>(),discard=ref<HTMLDialogElement>(),input=ref<HTMLTextAreaElement>()
const personal=ref<PersonalWriting>(),text=ref(''),baseline=ref(''),busy=ref(false),saving=ref(false),loadError=ref(''),favoriteError=ref(''),saveError=ref(''),fieldError=ref(''),notice=ref(''),conflict=ref(false)
const current=computed(()=>personal.value?personal.value.material:props.material),basis=computed(()=>personal.value?.imitation?.snapshot??current.value?.content),available=computed(()=>personal.value?personal.value.available:!!props.material),dirty=computed(()=>text.value!==baseline.value)
let controller:AbortController|undefined,mutation:AbortController|undefined,epoch=0,request=0,disposed=false,pending:'favorite'|'save'|null=null,desiredFavorite=true,discardResolve:((value:boolean)=>void)|undefined
function valid(ticket:number,identity:number){return !disposed&&ticket===epoch&&identity===getGeneration()}
async function open(){await nextTick();if(!disposed&&!dialog.value?.open)dialog.value?.showModal()}
async function load(preserve=false){if(!auth.user)return;const seq=++request,ticket=epoch,identity=getGeneration();controller?.abort();controller=new AbortController();busy.value=true;loadError.value='';try{const data=await writingPersonal(props.materialId,controller.signal);if(!valid(ticket,identity)||seq!==request)return;personal.value=data;baseline.value=data.imitation?.text??'';if(!preserve)text.value=baseline.value;emit('changed',data)}catch(e){if(valid(ticket,identity)&&seq===request&&!(e instanceof DOMException&&e.name==='AbortError'))loadError.value=errorMessage(e)}finally{if(valid(ticket,identity)&&seq===request)busy.value=false}}
function authenticate(action:'favorite'|'save'){pending=action;intent.begin({materialId:props.materialId,route:route.fullPath,action,favorite:desiredFavorite,draft:text.value,revision:props.material?.revision});dialog.value?.close();login.request()}
async function favorite(value=!personal.value?.favorite){if(saving.value||busy.value)return;desiredFavorite=value;if(!auth.user){authenticate('favorite');return}if(!personal.value){await load(true);if(!personal.value)return}const ticket=epoch,identity=getGeneration();saving.value=true;favoriteError.value='';mutation=new AbortController();const isCurrent=()=>valid(ticket,identity);try{if(value){const data=await setWritingFavorite(props.materialId,current.value?.revision??0,mutation.signal,isCurrent);if(!isCurrent())return;personal.value={...personal.value!,favorite:data.favorite,available:data.available,material:data.material}}else{await cancelWritingFavorite(props.materialId,mutation.signal,isCurrent);if(!isCurrent())return;personal.value={...personal.value!,favorite:false}}emit('changed',personal.value!)}catch(e){if(isCurrent())favoriteError.value=errorMessage(e)}finally{if(isCurrent())saving.value=false}}
async function save(){if(saving.value||busy.value)return;fieldError.value='';const value=text.value.trim();if(!value||value.length>2000||!/[a-z]/i.test(value)){fieldError.value='请写一句包含英文的句子，最多2000字符。';await nextTick();input.value?.focus();return}if(!auth.user){authenticate('save');return}if(!personal.value){await load(true);if(!personal.value)return}if(!available.value)return;const ticket=epoch,identity=getGeneration();saving.value=true;saveError.value='';notice.value='';conflict.value=false;mutation=new AbortController();const isCurrent=()=>valid(ticket,identity);try{const own=personal.value.imitation;const data=await saveWritingImitation(props.materialId,value,own?.materialRevision??current.value!.revision,own?.lockVersion??0,mutation.signal,isCurrent);if(!isCurrent())return;personal.value=data;text.value=data.imitation!.text;baseline.value=text.value;notice.value='仿写已保存';emit('changed',data)}catch(e){if(isCurrent()){saveError.value=errorMessage(e);conflict.value=e instanceof ApiError&&['IMITATION_CONFLICT','WRITING_CHANGED'].includes(e.code??'')}}finally{if(isCurrent())saving.value=false}}
async function latest(){await load(true);if(!loadError.value){notice.value='已加载最新记录，你的草稿仍保留在输入框；请对照后再保存。';conflict.value=false}}
async function mayLeave(){if(saving.value)return false;const ticket=epoch;if(dirty.value){if(discardResolve)return false;discard.value?.showModal();const keep=await new Promise<boolean>(resolve=>{discardResolve=resolve});if(!keep||disposed||ticket!==epoch)return false}return true}
async function close(){if(!await mayLeave())return;dialog.value?.close();emit('close')}
function discardChoice(value:boolean){discard.value?.close();discardResolve?.(value);discardResolve=undefined}
function wipe(){epoch++;request++;controller?.abort();mutation?.abort();personal.value=undefined;text.value='';baseline.value='';pending=null;discardChoice(false);dialog.value?.close();emit('close')}
const unsubscribe=onRemoteIdentityChange(wipe)
watch(()=>auth.user?.id,(value,previous)=>{if(previous&&previous!==value)wipe()},{flush:'sync'})
watch(()=>login.open,async value=>{if(value||!pending||disposed||auth.user)return;pending=null;intent.clear();await open()})
function unloading(event:BeforeUnloadEvent){if(dirty.value&&!saving.value){event.preventDefault();event.returnValue=''}}
onBeforeRouteLeave(mayLeave);onBeforeRouteUpdate((to,from)=>to.fullPath===from.fullPath?true:mayLeave())
onMounted(async()=>{window.addEventListener('beforeunload',unloading);if(props.resume)text.value=props.resume.draft;await open();await load(!!props.resume);if(props.resume&&!loadError.value&&personal.value){if(props.resume.expires<Date.now()){notice.value='登录耗时较长，草稿已保留，请手动确认操作。';return}if(props.resume.action==='favorite'){await favorite(props.resume.favorite);return}if(personal.value.imitation){notice.value='账号已有仿写，你的草稿仍保留；请对照后手动保存。';return}if(props.resume.revision!==current.value?.revision){saveError.value='素材已更新，草稿已保留，请确认当前参考后手动保存。';return}await save();return}if(props.initialFavorite!==undefined)await favorite(props.initialFavorite)})
onBeforeUnmount(()=>{disposed=true;epoch++;controller?.abort();mutation?.abort();unsubscribe();window.removeEventListener('beforeunload',unloading);discardResolve?.(false);discard.value?.close();dialog.value?.close()})
</script>
<template><Teleport to="body"><dialog ref="dialog" class="reader-writing-dialog" aria-labelledby="writing-detail-title" @cancel.prevent="close"><header><h2 id="writing-detail-title">写作积累</h2><button type="button" aria-label="关闭写作详情" :disabled="saving" @click="close">×</button></header><p v-if="busy" role="status">正在加载个人记录…</p><div v-if="loadError" role="alert"><p>{{ loadError }}</p><button class="button-secondary" type="button" @click="load(true)">重试个人记录</button></div><p v-if="personal&&!available" class="reader-local-message">素材已下架或暂不可访问，已有仿写快照只读保留，仍可取消收藏。</p><p v-if="personal?.imitation&&current&&personal.imitation.materialRevision!==current.revision" class="reader-rail-note">素材已更新，以下保留这条仿写原来参照的内容。</p><WritingContentBody v-if="basis" :content="basis"/><div class="writing-personal-actions"><button class="button-secondary" type="button" :disabled="busy||saving||!!loadError||(!available&&!personal?.favorite)" @click="favorite()">{{ personal?.favorite?'取消收藏':'收藏素材' }}</button><p v-if="favoriteError" role="alert">{{ favoriteError }}</p></div><form class="writing-imitation-form" @submit.prevent="save"><label for="writing-imitation-input">我的仿写</label><p class="reader-rail-note">试着换个话题，用这个句型写一句英文。只保存内容，不进行AI评分。</p><textarea id="writing-imitation-input" ref="input" v-model="text" rows="4" maxlength="2000" :readonly="!!personal&&!available" :disabled="saving||busy" :aria-invalid="fieldError?'true':undefined" aria-describedby="writing-imitation-error" @input="fieldError='';notice=''"/><p id="writing-imitation-error" class="auth-field-error" role="alert">{{ fieldError }}</p><p v-if="saveError" role="alert" class="auth-field-error">{{ saveError }}</p><button v-if="conflict" type="button" class="button-secondary" :disabled="busy||saving" @click="latest">加载最新记录并保留草稿</button><p v-if="notice" role="status" class="reader-local-message">{{ notice }}</p><p v-if="notice&&personal?.imitation&&personal.imitation.text!==text" class="writing-latest-text">最新已保存内容：{{ personal.imitation.text }}</p><div class="writing-imitation-footer"><span>{{ dirty?'有未保存修改':'内容已同步' }}</span><button class="button-primary" :disabled="busy||saving||!!loadError||!available">{{ saving?'正在保存…':'保存仿写' }}</button></div></form></dialog><dialog ref="discard" class="reader-writing-confirm" aria-labelledby="writing-discard-title" @cancel.prevent="discardChoice(false)"><h2 id="writing-discard-title">还有未保存的仿写</h2><p>关闭会放弃当前修改，已经保存的记录保留。</p><div class="reading-actions"><button class="button-primary" @click="discardChoice(false)">继续编辑</button><button class="button-secondary" @click="discardChoice(true)">放弃修改并关闭</button></div></dialog></Teleport></template>
